"""File utility helpers using os.path."""
import os


def file_exists(path: str) -> bool:
    """Return True if path points to an existing file."""
    return os.path.isfile(path)


def ensure_dir(path: str) -> str:
    """Create directory and all parents if they don't exist. Returns the path."""
    os.makedirs(path, exist_ok=True)
    return path


def join_paths(*parts: str) -> str:
    """Join path components."""
    return os.path.join(*parts)


def get_extension(path: str) -> str:
    """Return the file extension including the dot, e.g. '.txt'. Empty string if none."""
    _, ext = os.path.splitext(path)
    return ext


def list_files(directory: str, extension: str = "") -> list:
    """Return sorted list of files in directory, optionally filtered by extension."""
    if not os.path.isdir(directory):
        return []
    result = []
    for entry in os.listdir(directory):
        full = os.path.join(directory, entry)
        if os.path.isfile(full):
            if not extension or entry.endswith(extension):
                result.append(entry)
    return sorted(result)
